{"type":"message","message":{"id":"gen-1775376847-LE1KwoglNKYfwBKUPlgq","role":"assistant","created":1775376879,"content":[{"type":"thinking","thinking":"Let me try to implement polynomial regression manually without numpy or scipy.\n","signature":""},{"type":"toolRequest","id":"call_066469ed002e4015bda8e29f","toolCall":{"status":"success","value":{"name":"shell","arguments":{"command":"python3 << 'EOF'\nimport math\n\n# Extract surplus/deficit data for calendar years 1989-2013\ndata = {\n    # From treasury_bulletin_1994_06_page_28.txt\n    1989: -152087,\n    1990: -220388,\n    1991: -268729,\n    1992: -290204,\n    1993: -254948,\n    # From treasury_bulletin_1999_06_page_15.txt\n    1994: -203370,\n    1995: -163813,\n    1996: -107331,\n    1997: -22618,\n    1998: 70039,\n    # From treasury_bulletin_2004_06_page_18.txt\n    1999: 125974,\n    2000: 236917,\n    2001: 127401,\n    2002: -157823,\n    2003: -374791,\n    # From treasury_bulletin_2009_06_page_20.txt\n    2004: -412986,\n    2005: -318298,\n    2006: -248197,\n    2007: -161527,\n    2008: -454798,\n    # From treasury_bulletin_2014_06_page_19.txt\n    2009: -1415722,\n    2010: -1294204,\n    2011: -1295591,\n    2012: -1089353,\n    2013: -680276,\n}\n\n# Filter to 1989-2013\nyears = list(range(1989, 2014))\ny = [data[year] for year in years]\n\nprint(\"Calendar year data (1989-2013):\")\nfor year, val in zip(years, y):\n    print(f\"{year}: {val:,}\")\n\n# Fit cubic polynomial using least squares (manual implementation)\n# y = a3*x^3 + a2*x^2 + a1*x + a0\n# We need to solve X^T * X * beta = X^T * y\n\n# Create the design matrix\nX_design = []\nfor x in years:\n    X_design.append([x**3, x**2, x, 1])\n\n# Solve using normal equations: (X'X)^(-1) * X'y\n# First compute X'X (4x4 matrix)\nXTX = [[0]*4 for _ in range(4)]\nfor i in range(4):\n    for j in range(4):\n        for k in range(len(years)):\n            XTX[i][j] += X_design[k][i] * X_design[k][j]\n\n# Compute X'y (4x1 vector)\nXTy = [0]*4\nfor i in range(4):\n    for k in range(len(years)):\n        XTy[i] += X_design[k][i] * y[k]\n\n# Now solve the 4x4 linear system using Gaussian elimination\nn = 4\n# Augment matrix\nA = [XTX[i][:] + [XTy[i]] for i in range(n)]\n\n# Forward elimination\nfor i in range(n):\n    # Find pivot\n    max_row = i\n    for r in range(i+1, n):\n        if abs(A[r][i]) > abs(A[max_row][i]):\n            max_row = r\n    A[i], A[max_row] = A[max_row], A[i]\n    \n    # Make sure diagonal is not zero\n    if abs(A[i][i]) < 1e-10:\n        continue\n    \n    # Eliminate\n    for r in range(i+1, n):\n        factor = A[r][i] / A[i][i]\n        for c in range(i, n+1):\n            A[r][c] -= factor * A[i][c]\n\n# Back substitution\nx = [0]*n\nfor i in range(n-1, -1, -1):\n    if abs(A[i][i]) < 1e-10:\n        x[i] = 0\n    else:\n        x[i] = A[i][n]\n        for c in range(i+1, n):\n            x[i] -= A[i][c] * x[c]\n        x[i] /= A[i][i]\n\na3, a2, a1, a0 = x\nprint(f\"\\nCubic polynomial coefficients:\")\nprint(f\"  a3: {a3:.6f}\")\nprint(f\"  a2: {a2:.6f}\")\nprint(f\"  a1: {a1:.6f}\")\nprint(f\"  a0: {a0:.6f}\")\n\n# Predict for 2025\nx_2025 = 2025\nprediction_2025 = a3*x_2025**3 + a2*x_2025**2 + a1*x_2025 + a0\nprint(f\"\\nPrediction for 2025: {prediction_2025:,.2f} million dollars\")\n\n# Check fit quality\ny_pred = [a3*x**3 + a2*x**2 + a1*x + a0 for x in years]\nss_res = sum((y[i] - y_pred[i])**2 for i in range(len(y)))\ny_mean = sum(y) / len(y)\nss_tot = sum((y[i] - y_mean)**2 for i in range(len(y)))\nr2 = 1 - (ss_res / ss_tot)\nprint(f\"R-squared: {r2:.4f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
